// Lightweight utility functions to replace lodash/mathjs
const sortBy = <T,>(arr: T[], key: keyof T | ((item: T) => number)): T[] => {
  const keyFn = typeof key === 'function' ? key : (item: T) => item[key];
  return [...arr].sort((a, b) => {
    const aVal = keyFn(a);
    const bVal = keyFn(b);
    return aVal < bVal ? -1 : aVal > bVal ? 1 : 0;
  });
};

const meanBy = <T,>(arr: T[], key: keyof T): number => {
  const sum = arr.reduce((acc, item) => acc + (item[key] as unknown as number), 0);
  return sum / arr.length;
};

const sumBy = <T,>(arr: T[], key: keyof T): number => {
  return arr.reduce((acc, item) => acc + (item[key] as unknown as number), 0);
};

const maxBy = <T,>(arr: T[], key: keyof T): T | undefined => {
  return arr.reduce((max, item) => {
    const maxVal = max ? (max[key] as unknown as number) : -Infinity;
    const itemVal = item[key] as unknown as number;
    return itemVal > maxVal ? item : max;
  });
};

const minBy = <T,>(arr: T[], key: keyof T): T | undefined => {
  return arr.reduce((min, item) => {
    const minVal = min ? (min[key] as unknown as number) : Infinity;
    const itemVal = item[key] as unknown as number;
    return itemVal < minVal ? item : min;
  });
};

// Statistical functions
const mean = (arr: number[]): number => arr.reduce((a, b) => a + b, 0) / arr.length;

const median = (arr: number[]): number => {
  const sorted = [...arr].sort((a, b) => a - b);
  const mid = Math.floor(sorted.length / 2);
  return sorted.length % 2 ? sorted[mid] : (sorted[mid - 1] + sorted[mid]) / 2;
};

const variance = (arr: number[]): number => {
  const m = mean(arr);
  return arr.reduce((acc, val) => acc + Math.pow(val - m, 2), 0) / arr.length;
};

const std = (arr: number[]): number => Math.sqrt(variance(arr));

const quantileSeq = (arr: number[], q: number): number => {
  const sorted = [...arr].sort((a, b) => a - b);
  const index = q * (sorted.length - 1);
  const lower = Math.floor(index);
  const upper = Math.ceil(index);
  const weight = index % 1;

  if (lower === upper) return sorted[lower];
  return sorted[lower] * (1 - weight) + sorted[upper] * weight;
};

